DO $$ DECLARE def text; old text:='items:=items||jsonb_build_array(jsonb_build_object(''instance_id'',inst.id'; BEGIN def:=pg_get_functiondef('public.gw_read_exchange(text,text,timestamptz,text,text,public.gw_app,text,jsonb)'::regprocedure); IF position(old IN def)=0 THEN RAISE EXCEPTION 'stale suppression anchor missing'; END IF; def:=replace(def,old,'IF stale THEN facts:=jsonb_build_object(''unavailable'',''source revision/current episode not fresh; retry signed read''); END IF; '||old); EXECUTE def; END $$;